using System.Net;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.DependencyInjection;
using Tandem.Server.Art;
using Tandem.Server.Tests.Infrastructure;

namespace Tandem.Server.Tests.Art;

public class ArtEndpointTests
{
    private const string Email = "art@example.com";

    /// <summary>A PNG signature followed by generated bytes: never a real cover.</summary>
    internal static byte[] FakePng(int size = 64)
    {
        var bytes = new byte[size];
        new Random(7).NextBytes(bytes);
        byte[] magic = [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A];
        magic.CopyTo(bytes, 0);
        return bytes;
    }

    /// <summary>Answers outbound art requests from a function and counts them.</summary>
    internal sealed class FakeSources(Func<Uri, HttpResponseMessage> answer) : HttpMessageHandler
    {
        private int _calls;
        public int Calls => _calls;
        public List<Uri> Seen { get; } = [];
        public List<string> UserAgents { get; } = [];

        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken ct)
        {
            Interlocked.Increment(ref _calls);
            lock (Seen)
            {
                Seen.Add(request.RequestUri!);
                UserAgents.Add(request.Headers.UserAgent.ToString());
            }
            return Task.FromResult(answer(request.RequestUri!));
        }

        public static HttpResponseMessage NotFound() => new(HttpStatusCode.NotFound) { Content = new StringContent("<html>404</html>", Encoding.UTF8, "text/html") };

        public static HttpResponseMessage Image(byte[] bytes)
        {
            var content = new ByteArrayContent(bytes);
            content.Headers.ContentType = new("image/png");
            return new HttpResponseMessage(HttpStatusCode.OK) { Content = content };
        }
    }

    private static ServerFactory Factory(FakeSources sources, bool enabled = true, long? maxImageBytes = null)
    {
        var f = new ServerFactory();
        f.Settings["Tandem:EnableArt"] = enabled ? "true" : "false";
        if (maxImageBytes is { } max) f.Settings["Tandem:ArtMaxImageBytes"] = max.ToString(System.Globalization.CultureInfo.InvariantCulture);
        f.ConfigureExtraServices = s => s.AddHttpClient(ArtFetcher.ClientName).ConfigurePrimaryHttpMessageHandler(() => sources);
        return f;
    }

    private static Task Drain(ServerFactory f) => f.Services.GetRequiredService<ArtFetcher>().WhenIdleAsync().WaitAsync(TimeSpan.FromSeconds(10));

    private static async Task<string?> ErrorCode(HttpResponseMessage r)
    {
        using var doc = JsonDocument.Parse(await r.Content.ReadAsStringAsync());
        return doc.RootElement.GetProperty("error").GetString();
    }

    /// <summary>The header as the server wrote it (the typed header reorders its parts).</summary>
    private static string CacheControl(HttpResponseMessage r) => r.Headers.NonValidated["Cache-Control"].ToString();

    private static readonly Uri SsxCover = new("https://art.gametdb.com/wii/cover/US/GXBE69.png");

    [Fact]
    public async Task Unknown_game_is_not_found()
    {
        var sources = new FakeSources(_ => FakeSources.Image(FakePng()));
        using var f = Factory(sources);
        var (device, _) = await f.Register(Email);

        var r = await device.GetAsync("/v1/web/art/dolphin/GXBE69");

        Assert.Equal(HttpStatusCode.NotFound, r.StatusCode);
        Assert.Equal("not_found", await ErrorCode(r));
        Assert.Equal(0, sources.Calls);
    }

    [Fact]
    public async Task First_request_is_pending_then_image()
    {
        var png = FakePng();
        var sources = new FakeSources(u => u == SsxCover ? FakeSources.Image(png) : FakeSources.NotFound());
        using var f = Factory(sources);
        var (device, _) = await f.Register(Email);
        await device.UploadSave("GXBE69", "card", null, "dolphin");

        var first = await device.GetAsync("/v1/web/art/dolphin/GXBE69");
        Assert.Equal(HttpStatusCode.Accepted, first.StatusCode);
        Assert.Equal("art_pending", await ErrorCode(first));
        Assert.Equal("3", first.Headers.GetValues("Retry-After").Single());
        Assert.Equal("no-store", CacheControl(first));

        await Drain(f);
        var second = await device.GetAsync("/v1/web/art/dolphin/GXBE69");

        Assert.Equal(HttpStatusCode.OK, second.StatusCode);
        Assert.Equal("image/png", second.Content.Headers.ContentType!.MediaType);
        Assert.NotNull(second.Headers.ETag);
        Assert.Equal("private, max-age=604800", CacheControl(second));
        Assert.Equal(png, await second.Content.ReadAsByteArrayAsync());
        Assert.Equal(1, sources.Calls);
        Assert.Equal(["Tandem-server"], sources.UserAgents);

        using var conditional = new HttpRequestMessage(HttpMethod.Get, "/v1/web/art/dolphin/GXBE69");
        conditional.Headers.IfNoneMatch.Add(second.Headers.ETag!);
        Assert.Equal(HttpStatusCode.NotModified, (await device.SendAsync(conditional)).StatusCode);
    }

    [Fact]
    public async Task Source_miss_is_remembered()
    {
        var sources = new FakeSources(_ => FakeSources.NotFound());
        using var f = Factory(sources);
        var (device, _) = await f.Register(Email);
        await device.UploadSave("GXBE69", "card", null, "dolphin");

        Assert.Equal(HttpStatusCode.Accepted, (await device.GetAsync("/v1/web/art/dolphin/GXBE69")).StatusCode);
        await Drain(f);
        var second = await device.GetAsync("/v1/web/art/dolphin/GXBE69");
        Assert.Equal(HttpStatusCode.NotFound, second.StatusCode);
        Assert.Equal("no_art", await ErrorCode(second));
        Assert.Equal("private, max-age=86400", CacheControl(second));
        var calls = sources.Calls;
        Assert.True(calls > 0);

        f.Time.Advance(TimeSpan.FromDays(6));
        var third = await device.GetAsync("/v1/web/art/dolphin/GXBE69");
        await Drain(f);
        Assert.Equal(HttpStatusCode.NotFound, third.StatusCode);
        Assert.Equal(calls, sources.Calls);

        f.Time.Advance(TimeSpan.FromDays(2)); // past ArtMissDays: the sources are asked again
        Assert.Equal(HttpStatusCode.Accepted, (await device.GetAsync("/v1/web/art/dolphin/GXBE69")).StatusCode);
        await Drain(f);
        Assert.True(sources.Calls > calls);
    }

    [Fact]
    public async Task An_unreachable_source_is_a_short_transient_miss()
    {
        var sources = new FakeSources(_ => new HttpResponseMessage(HttpStatusCode.ServiceUnavailable));
        using var f = Factory(sources);
        var (device, _) = await f.Register(Email);
        await device.UploadSave("GXBE69", "card", null, "dolphin");

        Assert.Equal(HttpStatusCode.Accepted, (await device.GetAsync("/v1/web/art/dolphin/GXBE69")).StatusCode);
        await Drain(f);
        var second = await device.GetAsync("/v1/web/art/dolphin/GXBE69");

        Assert.Equal(HttpStatusCode.NotFound, second.StatusCode);
        Assert.Equal("art_unavailable", await ErrorCode(second)); // not no_art: clients don't remember it
        Assert.Equal("private, max-age=3600", CacheControl(second));

        f.Time.Advance(TimeSpan.FromMinutes(45));
        var later = await device.GetAsync("/v1/web/art/dolphin/GXBE69");
        Assert.Equal("private, max-age=900", CacheControl(later)); // only for what is left of the hour

        f.Time.Advance(TimeSpan.FromMinutes(16));
        Assert.Equal(HttpStatusCode.Accepted, (await device.GetAsync("/v1/web/art/dolphin/GXBE69")).StatusCode);
    }

    [Fact]
    public async Task A_failed_save_is_a_transient_miss_not_a_refetch_per_request()
    {
        var sources = new FakeSources(u => u == SsxCover ? FakeSources.Image(FakePng()) : FakeSources.NotFound());
        using var f = Factory(sources);
        var (device, _) = await f.Register(Email);
        await device.UploadSave("GXBE69", "card", null, "dolphin");
        // A directory where the image should go makes the store's move fail, as a full or read-only disk would.
        Directory.CreateDirectory(Path.Combine(f.DataDirectory, "art", ArtStore.NameOf("dolphin", "GXBE69") + ".png"));

        Assert.Equal(HttpStatusCode.Accepted, (await device.GetAsync("/v1/web/art/dolphin/GXBE69")).StatusCode);
        await Drain(f);
        var calls = sources.Calls;
        var second = await device.GetAsync("/v1/web/art/dolphin/GXBE69");
        await Drain(f);

        Assert.Equal(HttpStatusCode.NotFound, second.StatusCode);
        Assert.Equal("art_unavailable", await ErrorCode(second));
        Assert.Equal(calls, sources.Calls);
    }

    [Fact]
    public async Task The_size_cap_holds_without_a_content_length()
    {
        var big = FakePng(4096);
        var sources = new FakeSources(u => u == SsxCover
            ? new HttpResponseMessage(HttpStatusCode.OK) { Content = new StreamContent(new OneWayStream(big)) }
            : FakeSources.NotFound());
        using var f = Factory(sources, maxImageBytes: 1024);
        var (device, _) = await f.Register(Email);
        await device.UploadSave("GXBE69", "card", null, "dolphin");

        Assert.Equal(HttpStatusCode.Accepted, (await device.GetAsync("/v1/web/art/dolphin/GXBE69")).StatusCode);
        await Drain(f);
        var r = await device.GetAsync("/v1/web/art/dolphin/GXBE69");

        Assert.Equal(HttpStatusCode.NotFound, r.StatusCode);
        Assert.Equal("no_art", await ErrorCode(r));
        Assert.Empty(Directory.GetFiles(Path.Combine(f.DataDirectory, "art"), "*.png"));
    }

    [Fact]
    public async Task Content_without_a_length_is_capped_while_streaming()
    {
        var content = new StreamContent(new OneWayStream(FakePng(200_000)));
        Assert.Null(content.Headers.ContentLength); // so the header check can't catch it
        Assert.Null(await ArtFetcher.ReadCappedAsync(content, 100_000, default));
        var small = new StreamContent(new OneWayStream(FakePng(500)));
        Assert.Equal(500, (await ArtFetcher.ReadCappedAsync(small, 100_000, default))!.Length);
    }

    /// <summary>A body that can't seek, so it has no Content-Length, as a chunked response.</summary>
    private sealed class OneWayStream(byte[] bytes) : MemoryStream(bytes)
    {
        public override bool CanSeek => false;
    }

    [Fact]
    public async Task Non_image_and_oversized_are_misses()
    {
        var html = Encoding.UTF8.GetBytes("<!DOCTYPE html><html><body>not a cover</body></html>");
        var big = FakePng(2048);
        var sources = new FakeSources(u => u.AbsolutePath.Contains("GXBE69")
            ? new HttpResponseMessage(HttpStatusCode.OK) { Content = new ByteArrayContent(html) }
            : u.AbsolutePath.Contains("GALE01") ? FakeSources.Image(big) : FakeSources.NotFound());
        using var f = Factory(sources, maxImageBytes: 1024);
        var (device, _) = await f.Register(Email);
        await device.UploadSave("GXBE69", "card", null, "dolphin");
        await device.UploadSave("GALE01", "card", null, "dolphin");

        Assert.Equal(HttpStatusCode.Accepted, (await device.GetAsync("/v1/web/art/dolphin/GXBE69")).StatusCode);
        Assert.Equal(HttpStatusCode.Accepted, (await device.GetAsync("/v1/web/art/dolphin/GALE01")).StatusCode);
        await Drain(f);

        foreach (var key in new[] { "GXBE69", "GALE01" })
        {
            var r = await device.GetAsync($"/v1/web/art/dolphin/{key}");
            Assert.Equal(HttpStatusCode.NotFound, r.StatusCode);
            Assert.Equal("no_art", await ErrorCode(r));
        }
        var art = Path.Combine(f.DataDirectory, "art");
        Assert.Empty(Directory.Exists(art) ? Directory.GetFiles(art, "*.*").Where(p => !p.EndsWith(".miss", StringComparison.Ordinal)) : []);
    }

    [Fact]
    public async Task Slash_and_unicode_keys_round_trip()
    {
        const string key = "GBA/Pokémon - Emerald Version (USA).srm";
        var png = FakePng();
        var listing = """
            { "tree": [
              { "path": "Pokemon - Emerald Version (Europe).png", "mode": "100644", "type": "blob", "size": 900 },
              { "path": "Pokemon - Emerald Version (USA, Europe).png", "mode": "100644", "type": "blob", "size": 900 },
              { "path": "Pokemon - Emerald Version (USA).png", "mode": "120000", "type": "blob", "size": 40 }
            ] }
            """;
        var cover = LibretroThumbnailSource.FileUri("Nintendo_-_Game_Boy_Advance", "Pokemon - Emerald Version (USA, Europe).png");
        var sources = new FakeSources(u =>
            u == LibretroIndex.ListingUri("Nintendo_-_Game_Boy_Advance") ? new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent(listing) }
            : u == cover ? FakeSources.Image(png)
            : FakeSources.NotFound());
        using var f = Factory(sources);
        var (device, _) = await f.Register(Email);
        await device.UploadSave(key, "sram", null, "retroarch");

        // The web client's encoding: each segment with encodeURIComponent, '/' kept as the separator.
        var url = "/v1/web/art/retroarch/" + string.Join("/", key.Split('/').Select(EncodeUriComponent));
        Assert.Equal(HttpStatusCode.Accepted, (await device.GetAsync(url)).StatusCode);
        await Drain(f);
        var r = await device.GetAsync(url);

        Assert.Equal(HttpStatusCode.OK, r.StatusCode);
        Assert.Equal(png, await r.Content.ReadAsByteArrayAsync());
        // An encoded slash (%2F, as the app's encodeSegment sends it) names the same game.
        Assert.Equal(HttpStatusCode.OK, (await device.GetAsync("/v1/web/art/retroarch/" + Uri.EscapeDataString(key))).StatusCode);
    }

    [Fact]
    public async Task An_installed_game_without_a_save_gets_art_by_its_reported_system()
    {
        var png = FakePng();
        var listing = """{ "tree": [ { "path": "Golden Sun (USA, Europe).png", "mode": "100644", "type": "blob", "size": 900 } ] }""";
        var cover = LibretroThumbnailSource.FileUri("Nintendo_-_Game_Boy_Advance", "Golden Sun (USA, Europe).png");
        var sources = new FakeSources(u =>
            u == LibretroIndex.ListingUri("Nintendo_-_Game_Boy_Advance") ? new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent(listing) }
            : u == cover ? FakeSources.Image(png)
            : FakeSources.NotFound());
        using var f = Factory(sources);
        var (device, _) = await f.Register(Email);
        await device.PutAsJsonAsync("/v1/devices/me/installs/retroarch",
            new Tandem.Protocol.InstallsRequest([new Tandem.Protocol.InstalledGame("retroarch/Golden Sun", "Golden Sun", null, "GBA")]));

        const string url = "/v1/web/art/retroarch/retroarch/Golden%20Sun";
        Assert.Equal(HttpStatusCode.Accepted, (await device.GetAsync(url)).StatusCode);
        await Drain(f);
        var r = await device.GetAsync(url);

        Assert.Equal(HttpStatusCode.OK, r.StatusCode);
        Assert.Equal(png, await r.Content.ReadAsByteArrayAsync());
    }

    [Fact]
    public async Task Another_users_installed_game_is_not_found()
    {
        var sources = new FakeSources(_ => FakeSources.Image(FakePng()));
        using var f = Factory(sources);
        f.Settings["Tandem:AllowRegistration"] = "true";
        var (owner, _) = await f.Register(Email);
        await owner.PutAsJsonAsync("/v1/devices/me/installs/retroarch",
            new Tandem.Protocol.InstallsRequest([new Tandem.Protocol.InstalledGame("retroarch/Golden Sun", "Golden Sun", null, "GBA")]));
        var (other, _) = await f.Register("other@example.com");

        var r = await other.GetAsync("/v1/web/art/retroarch/retroarch/Golden%20Sun");

        Assert.Equal(HttpStatusCode.NotFound, r.StatusCode);
        Assert.Equal("not_found", await ErrorCode(r));
        Assert.Equal(0, sources.Calls);
    }

    /// <summary>JavaScript's encodeURIComponent: like EscapeDataString, but leaves !'()* alone.</summary>
    private static string EncodeUriComponent(string s) =>
        Uri.EscapeDataString(s).Replace("%21", "!").Replace("%27", "'").Replace("%28", "(").Replace("%29", ")").Replace("%2A", "*");

    [Fact]
    public async Task Disabled_art_is_no_art()
    {
        var sources = new FakeSources(_ => FakeSources.Image(FakePng()));
        using var f = Factory(sources, enabled: false);
        var (device, _) = await f.Register(Email);
        await device.UploadSave("GXBE69", "card", null, "dolphin");

        var r = await device.GetAsync("/v1/web/art/dolphin/GXBE69");

        Assert.Equal(HttpStatusCode.NotFound, r.StatusCode);
        Assert.Equal("no_art", await ErrorCode(r));
        Assert.Equal("private, max-age=86400", CacheControl(r));
        await Drain(f);
        Assert.Equal(0, sources.Calls);
    }

    [Fact]
    public async Task Device_key_and_web_session_both_work()
    {
        var sources = new FakeSources(u => u == SsxCover ? FakeSources.Image(FakePng()) : FakeSources.NotFound());
        using var f = Factory(sources);
        var (device, _) = await f.Register(Email);
        var web = await f.WebLogin(Email);
        await device.UploadSave("GXBE69", "card", null, "dolphin");

        Assert.Equal(HttpStatusCode.Accepted, (await device.GetAsync("/v1/web/art/dolphin/GXBE69")).StatusCode);
        // The fetch may already be done: either way, no second fetch is queued.
        Assert.Contains((await web.GetAsync("/v1/web/art/dolphin/GXBE69")).StatusCode, new[] { HttpStatusCode.Accepted, HttpStatusCode.OK });
        await Drain(f);
        Assert.Equal(HttpStatusCode.OK, (await web.GetAsync("/v1/web/art/dolphin/GXBE69")).StatusCode);
        Assert.Equal(HttpStatusCode.OK, (await device.GetAsync("/v1/web/art/dolphin/GXBE69")).StatusCode);
        Assert.Equal(1, sources.Calls); // the second 202 joined the queued fetch

        var anonymous = f.Client();
        Assert.Equal(HttpStatusCode.Unauthorized, (await anonymous.GetAsync("/v1/web/art/dolphin/GXBE69")).StatusCode);
    }

